PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?policyHolderId (COUNT(DISTINCT ?policy) AS ?policyCount)
WHERE {
  SERVICE <mapped> {
    ?policy a ins:Policy ;
            ins:hasPolicyHolder ?policyHolder ;
            ins:policyNumber ?policyNumber .
    ?policyHolder ins:policyHolderId ?policyHolderId .
  }
}
GROUP BY ?policyHolderId
ORDER BY ?policyHolderId

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?agentId ?policyNumber ?claimNumber ?lossPaymentAmount
WHERE {
  SERVICE <mapped> {
    ?agent a ins:Agent ;
           ins:agentId ?agentId .

    ?policy a ins:Policy ;
            ins:policyNumber ?policyNumber ;
            ins:soldByAgent ?agent .

    ?coverage a ins:PolicyCoverageDetail ;
              ins:hasPolicy ?policy .

    ?claim a ins:Claim ;
           ins:claimNumber ?claimNumber ;
           ins:against ?coverage ;
           ins:hasLossPayment ?lossPayment .

    ?lossPayment a ins:LossPayment ;
                 ins:lossPaymentAmount ?lossPaymentAmount .
  }
}
ORDER BY ?agentId ?policyNumber ?claimNumber

PREFIX ins: <http://data.world/schema/insurance/>

SELECT DISTINCT ?agent ?policy ?claim ?catastrophe
WHERE {
  SERVICE <mapped> {
    ?policy ins:soldByAgent ?agent .
    ?pcd ins:hasPolicy ?policy .
    ?claim ins:against ?pcd ;
           ins:hasCatastrophe ?catastrophe .
  }
}

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?policy ?policyHolderId
WHERE {
  SERVICE <mapped> {
    ?policy a ins:Policy ;
            ins:hasPolicyHolder ?policyHolder .
    ?policyHolder ins:policyHolderId ?policyHolderId .
  }
}

PREFIX ins: <http://data.world/schema/insurance/>

SELECT DISTINCT ?policy ?policyNumber ?claim ?claimNumber
WHERE {
  SERVICE <mapped> {
    ?claim a ins:Claim ;
           ins:claimNumber ?claimNumber ;
           ins:against ?pcd .

    ?pcd a ins:PolicyCoverageDetail ;
         ins:hasPolicy ?policy .

    ?policy a ins:Policy ;
            ins:policyNumber ?policyNumber .
  }
}
ORDER BY ?policyNumber ?claimNumber
